#!/usr/bin/env node

// The promo strip: one ClioTalk conversation, six Macintosh eras.
//
// This is the picture that makes the argument in one look. Six Finder
// screenshots would prove nothing, because the Finder really did exist in all
// six years. An LLM chat did not. So the strip shows the one window that could
// not have existed in 1988, wearing each decade in turn, with the same real
// conversation inside it.
//
// Every pixel is the running product. The reply is generated by a real local
// model over the app's own transport, once, before the eras are captured, so
// all six panels hold the identical text. Nothing here is typed in by hand and
// presented as model output.
//
//   npm start                          (app on :4173)
//   LM Studio serving on :1234         (or pass --endpoint)
//   node tooling/capture-promo-strip.mjs
//
// Output: internal/evidence/promo/
//   cliotalk-<era>.png      the six panels
//   cliotalk-six-eras.png   left to right, for X / Reddit / HN
//   cliotalk-grid.png       3 x 2, for phone-shaped feeds
//   promo-manifest.json     model, prompt, build, timestamps

import { mkdirSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { chromium } from "playwright";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const outDir = path.join(root, "internal", "evidence", "promo");
const appUrl = process.env.APP_URL || "http://localhost:4173/";

function flag(name, fallback) {
  const hit = process.argv.find((arg) => arg.startsWith(`--${name}=`));
  return hit ? hit.slice(name.length + 3) : fallback;
}

const endpoint = flag("endpoint", process.env.LM_STUDIO_BASE_URL || "http://127.0.0.1:1234");
const wantedModel = flag("model", "");
const PROMPT = flag("prompt",
  "Keep my voice, do not smooth it: rewrite \"They never called it renewable energy. "
  + "They called it the tide, and they billed it by the moon.\" in two sentences.");

const VIEW = { width: 1440, height: 900 };
const ERAS = [
  { id: "classic", year: 1988, label: "System 6" },
  { id: "platinum", year: 1999, label: "Platinum" },
  { id: "aqua", year: 2002, label: "Aqua" },
  { id: "snow-leopard", year: 2009, label: "Snow Leopard" },
  { id: "yosemite", year: 2014, label: "Yosemite" },
  { id: "liquid-glass", year: 2026, label: "Liquid Glass" },
];

// SwiftShader: the Liquid Glass era draws real WebGL, and a headless run with
// no GPU gives a black window without these.
const browser = await chromium.launch({
  args: ["--use-gl=swiftshader", "--enable-unsafe-swiftshader"],
});
const context = await browser.newContext({
  viewport: VIEW,
  deviceScaleFactor: 2,
  reducedMotion: "reduce",
});
await context.clock.setFixedTime(new Date("2026-08-13T10:07:00"));
// Balloon Help defaults on for hover-capable devices, and a headless browser
// is one. The pointer resting anywhere near the composer then floats a balloon
// over the reply. Store the same "off" a user would choose from the Help menu.
await context.addInitScript(() => {
  try { localStorage.setItem("ai-system6-balloon-help", "off"); } catch (e) {}
});
const page = await context.newPage();
page.on("pageerror", (e) => console.error("pageerror:", e.message));

await page.goto(appUrl, { waitUntil: "domcontentloaded" });
await page.waitForFunction(() => document.body.dataset.appReady === "ready", null, { timeout: 45000 });

// The Start Here guide steps aside, the same way a visitor closes it.
const guide = page.locator('[data-window="guide"]');
if (await guide.isVisible().catch(() => false)) {
  const legacy = guide.locator('[data-action="dismiss-guide"]');
  if (await legacy.isVisible().catch(() => false)) await legacy.click();
  else for (let step = 0; step < 3 && await guide.isVisible().catch(() => false); step += 1) {
    await guide.locator('[data-action="guide-continue"]').click().catch(() => {});
  }
  await guide.waitFor({ state: "hidden", timeout: 10000 }).catch(() => {});
}

// A real project disk, because ClioTalk writes into one.
await page.evaluate(() => handleAction("new-project-disk"));
await page.waitForSelector("#new-project-disk-modal[open]", { timeout: 10000 });
await page.fill("#new-project-disk-name", "The Tide Comes In Twice");
await page.click("#new-project-disk-confirm");
await page.waitForSelector("#new-project-disk-modal", { state: "hidden", timeout: 10000 });

// Connect the local model through the Control Panel's own controls, not an
// internal override, so the capture goes through the transport a user gets.
await page.evaluate(() => openWindow("control"));
await page.click("#control-tab-local");
const manual = page.locator("#local-manual-connection");
if (!await manual.evaluate((el) => el.open).catch(() => true)) {
  await manual.locator(":scope > summary").click();
}
// The Local tab is connect first, then choose. If it opens already holding a
// model from an earlier session, the endpoint field is not on screen: the
// connect button toggles the phase back.
const modelFields = page.locator(".local-model-fields");
if (await modelFields.isVisible().catch(() => false)) {
  await page.click("#connect-local-model");
  await modelFields.waitFor({ state: "hidden", timeout: 10000 }).catch(() => {});
}
await page.locator("#endpoint").waitFor({ state: "visible", timeout: 10000 });
await page.fill("#endpoint", endpoint);
await page.click("#connect-local-model");
// A populated model list is not a finished connection: the panel stays on
// "Connecting..." until the check completes, and ClioTalk keeps Send disabled
// until it does. Wait for the phase to flip, not for the first field to fill.
await modelFields.waitFor({ state: "visible", timeout: 60000 });
await page.waitForFunction(
  () => {
    const status = document.querySelector("#local-connection-status")?.textContent || "";
    const model = document.querySelector("#model")?.value || "";
    return /connected|已连接|连接成功/i.test(status) && model.trim() !== "";
  },
  null, { timeout: 60000 },
);
// ClioTalk enables Send on localModelState.ready || .loaded, so the model has
// to be one LM Studio has actually loaded, not merely one it can list. Ask the
// server which one is resident and take that, unless --model says otherwise.
let pick = wantedModel;
if (!pick) {
  try {
    const res = await fetch(`${endpoint.replace(/\/$/, "")}/api/v1/models`);
    const data = await res.json();
    const loaded = (data.models || []).find((item) =>
      item.type === "llm" && Array.isArray(item.loaded_instances) && item.loaded_instances.length > 0);
    pick = loaded?.loaded_instances?.[0]?.id || loaded?.key || "";
  } catch (e) {
    console.warn("could not read LM Studio model states:", e.message);
  }
}
if (pick) {
  await page.selectOption("#model-select", pick).catch(() => {});
  await page.evaluate((id) => {
    const input = document.querySelector("#model");
    if (!input) return;
    input.value = id;
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
  }, pick);
  await page.waitForTimeout(1200);
}
const model = await page.inputValue("#model");
console.log("connected:", endpoint, "model:", model);
await page.click('[data-window="control"] .close-box');

// One question, one real answer. Everything after this is photography.
await page.evaluate(() => openWindow("assistant"));
await page.waitForSelector('[data-window="assistant"]:not(.is-hidden)', { timeout: 15000 });
await page.fill("#prompt", PROMPT);
await page.locator("#send").waitFor({ state: "visible", timeout: 15000 });
await page.waitForFunction(() => !document.querySelector("#send")?.disabled, null, { timeout: 60000 });
await page.click("#send");
// Done is not "some text appeared": while ClioTalk works it shows its own
// progress card ("Consulting local model") inside the message list, and the
// submit button wears its Stop mode. Wait for the button to come back and for
// the last message to stop being the progress card.
await page.waitForFunction(
  () => {
    const send = document.querySelector("#send");
    if (!send || send.dataset.mode === "stop") return false;
    const last = [...document.querySelectorAll("#messages .message.assistant .message-content")].pop();
    const text = last?.textContent?.trim() || "";
    if (text.length < 60) return false;
    return !/Working locally|Consulting local model|Checking desk context|Typesetting reply|正在/i.test(text);
  },
  null, { timeout: 240000 },
);
await page.waitForTimeout(1500);
// Two things follow the pointer and the caret: Balloon Help, and the floating
// Dictation button the app parks beside whatever editable field is focused.
// Both are real product controls, and both would sit in the middle of a promo
// panel as an accident of automation. Give the focus back to the desk, the way
// a writer does when they stop typing, and let the app retract them.
await page.mouse.move(4, 880);
await page.evaluate(() => document.activeElement?.blur?.());
await page.waitForTimeout(600);
// Both elements live in the DOM all the time, so presence proves nothing:
// only a painted box would land in a panel.
const strayControls = await page.evaluate(() =>
  [...document.querySelectorAll("#dictation-field-button, #balloon-help")]
    .filter((el) => el.getClientRects().length > 0 && getComputedStyle(el).visibility !== "hidden")
    .map((el) => el.id));
if (strayControls.length) console.warn("still on screen at capture time:", strayControls.join(", "));
const reply = await page.evaluate(() =>
  [...document.querySelectorAll("#messages .message.assistant .message-content")].pop()?.textContent?.trim() || "");
console.log("reply:", reply.slice(0, 120).replace(/\s+/g, " "), "...");

// One window on an otherwise clear desk. Clearing is_hidden by hand is what
// makes openWindow think a window is already open, so hide the others only
// after ClioTalk is up, and never touch ClioTalk's own class.
await page.evaluate(() => {
  document.querySelectorAll(".window").forEach((win) => {
    if (win.dataset.window !== "assistant") win.classList.add("is-hidden");
  });
  const talk = document.querySelector('[data-window="assistant"]');
  if (talk) {
    talk.classList.remove("is-hidden");
    talk.style.left = "360px";
    talk.style.top = "150px";
    talk.style.width = "720px";
    talk.style.height = "600px";
    talk.dispatchEvent(new PointerEvent("pointerdown", { bubbles: true }));
  }
});
await page.waitForTimeout(600);

// The clip keeps a margin of the era's own desktop around the window, because
// the desk pattern, the gradient and the glass are half of what changed.
const MARGIN = 26;
const box = await page.locator('[data-window="assistant"]').boundingBox();
const clip = {
  x: Math.max(0, Math.round(box.x - MARGIN)),
  y: Math.max(0, Math.round(box.y - MARGIN)),
  width: Math.min(VIEW.width, Math.round(box.width + MARGIN * 2)),
  height: Math.min(VIEW.height, Math.round(box.height + MARGIN * 2)),
};

mkdirSync(outDir, { recursive: true });
const shots = [];
for (const era of ERAS) {
  await page.evaluate((id) => {
    const item = document.querySelector(`[data-action="set-theme-${id}"]`);
    if (!item) throw new Error("missing theme action: " + id);
    item.click();
  }, era.id);
  // Liquid Glass repaints its refraction layer; give it the longer beat.
  await page.waitForTimeout(era.id === "liquid-glass" ? 2200 : 1200);
  const file = path.join(outDir, `cliotalk-${era.id}.png`);
  const buffer = await page.screenshot({ path: file, clip });
  shots.push({ ...era, data: "data:image/png;base64," + buffer.toString("base64") });
  console.log("captured", era.id);
}

const build = await page.evaluate(async () => {
  try {
    const res = await fetch("/api/version");
    const data = await res.json();
    return data.build || data.version || null;
  } catch (e) { return null; }
});

// Compose in the app's own page: Chicago is already loaded there, so the
// sheet is captioned in the product's face without shipping a second copy of
// the font stack to this script.
async function compose(columns, file) {
  const data = await page.evaluate(async ({ shots, columns }) => {
    const images = await Promise.all(shots.map((shot) => new Promise((resolve, reject) => {
      const img = new Image();
      img.onload = () => resolve(img);
      img.onerror = reject;
      img.src = shot.data;
    })));
    const cellW = images[0].width;
    const cellH = images[0].height;
    const gap = Math.round(cellW * 0.035);
    const caption = Math.round(cellH * 0.1);
    const pad = gap;
    const rows = Math.ceil(images.length / columns);
    const canvas = document.createElement("canvas");
    canvas.width = pad * 2 + columns * cellW + (columns - 1) * gap;
    canvas.height = pad * 2 + rows * (cellH + caption) + (rows - 1) * gap;
    const ctx = canvas.getContext("2d");
    ctx.fillStyle = "#ffffff";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    images.forEach((img, index) => {
      const col = index % columns;
      const row = Math.floor(index / columns);
      const x = pad + col * (cellW + gap);
      const y = pad + row * (cellH + caption + gap);
      ctx.drawImage(img, x, y, cellW, cellH);
      ctx.fillStyle = "#000000";
      ctx.textBaseline = "top";
      const size = Math.round(cellH * 0.045);
      ctx.font = `${size}px Chicago_12, Chicago, sans-serif`;
      ctx.fillText(`${shots[index].year}  ${shots[index].label}`, x, y + cellH + Math.round(caption * 0.28));
    });
    return canvas.toDataURL("image/png");
  }, { shots, columns });
  writeFileSync(file, Buffer.from(data.split(",")[1], "base64"));
  console.log("wrote", path.relative(root, file));
}

await compose(6, path.join(outDir, "cliotalk-six-eras.png"));
await compose(3, path.join(outDir, "cliotalk-grid.png"));

writeFileSync(path.join(outDir, "promo-manifest.json"), JSON.stringify({
  capturedAt: new Date().toISOString(),
  build,
  endpoint,
  model,
  prompt: PROMPT,
  reply,
  viewport: VIEW,
  deviceScaleFactor: 2,
  clip,
  eras: ERAS.map((era) => ({ ...era, file: `cliotalk-${era.id}.png` })),
  note: "Every panel is the running app. The reply came from the local model once, before any era switch.",
}, null, 2) + "\n");

await browser.close();
console.log("promo strip written to", path.relative(root, outDir));
